"""Unit 38: Tagalog Basic Course, Semester I, Chapter 12, Lesson 1: Common Ailments.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, June 2017).
Pictures, audio, partner work and role plays are left out; the book's answer keys are used (misprints noted),
numbers and doses are written in words in the spoken lines."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


def P(rows):
    return [(t, e) for _, t, e in rows]


