        + [M("What are in/hin/nin verbs also called?", "object-focus or goal-focus verbs", ["doer-focus verbs", "pseudo verbs", "borrowed verbs"], "object-focus."), M("How do you form the past of a vowel-initial root like inom?", "prefix IN (inum becomes inINum)", ["infix IN", "invert to NI", "add um"], "prefix IN."), M("How do you form the past of a consonant-initial root like basa?", "infix IN (binasa)", ["prefix IN", "invert to NI", "add mag"], "infix."), M("What happens to IN with roots beginning with L, Y or R?", "it is inverted to NI and prefixed", ["it is infixed", "it is dropped", "it becomes um"], "NI."), M("What does tsekin mean?", "to check (test papers)", ["to cook", "to correct", "to hold up"], "tsekin."), M("What does holdapin mean?", "to hold up", ["to check", "to fire", "to attack"], "holdapin."), M("What does atakihin mean?", "to attack", ["to fire", "to correct", "to check"], "atakihin."), M("What does korekin mean?", "to correct", ["to check", "to attack", "to cook"], "korekin.")]
