        + [F("___ ninyo si David sa kanila para hindi siya mahawa. (keep away)", "Ilayo", ["Ilagay", "Ilipat"], "ilayo."), F("Nandoon ang gamot niya sa ___, sa tabi ng kama niya. (table)", "mesa", ["silid", "bimpo"], "mesa."), F("Kunan mo siya ng ___. (temperature)", "temperatura", ["gamot", "sopas"], "temperatura."), F("Hayaan mo siyang ___ at magpahinga. (sleep)", "matulog", ["tumakbo", "kumain"], "matulog.")]
