_D81 = [("Doctor", "O, ano ba’ng nangyari?", "Well, what happened?"), ("Patient", "Dok, masakit po ang kasu-kasuan ko at nananakit ang kalamnan ko. Nanginginig po ako sa ginaw. Ang sakit din po ng ulo ko. At may ubo at sipon din ako.", "Doc, my joints hurt and my muscles ache. I am trembling from the cold. My head also hurts a lot. And I have a cough and a cold too."), ("Doctor", "Kailan pa?", "Since when?"), ("Patient", "Nung isang gabi lang po, dok.", "Only the other night, doc."), ("Doctor", "May gamot ka bang iniinom?", "Are you taking any medicine?"), ("Patient", "Wala pa po. Hindi ko po kasi alam kung ano’ng iinumin ko.", "Not yet. I don’t know what to take.")]
