_VS = [("Bilhin nyo na po itong huling kahon ng mangga, mura lang po.", "Please buy this last box of mangoes, it’s cheap."), ("Binasa niya ang tuwalya at ibinigay sa bata.", "He wet the towel and gave it to the child."), ("Binisita ng doktor ang pasyente.", "The doctor visited the patient."), ("Dalasan mo naman ang pagbisita mo sa akin.", "Please visit me more often."), ("Puwede mo bang dalhin itong baon ni Cedric sa opisina niya?", "Can you bring this packed lunch of Cedric to his office?"), ("Dinasalan ni Father Yoy ang mga may sakit.", "Father Yoy prayed over the sick."), ("Huwag kang mag-alala, gagaling ka rin.", "Don’t worry, you will get well too."), ("Hinele ng nanay ang sanggol hanggang sa makatulog ito.", "The mother sang the baby a lullaby until he fell asleep."), ("Hinilot ka na ba ng arbularyo?", "Has the albularyo massaged you already?"), ("Ilayo mo ang pasyente para hindi makahawa.", "Isolate the patient so he won’t infect others."), ("Inilagay niya sa kahon ang mga binili niyang gamot.", "He put the medicines he bought in the box."), ("Inilipat na sa ibang silid ang pasyente.", "The patient has been moved to another room."), ("Kamutin mo naman ang likod ko, ang kati-kati kasi.", "Please scratch my back, it’s so itchy."), ("Kinuha mo na ba ang reseta sa mesa?", "Have you taken the prescription on the table?"), ("Magpepeklat ba ang sugat kapag kinamot?", "Will the wound scar if it is scratched?"), ("Lumipat ka ng kuwarto nang hindi ka mahawa.", "Move to another room so you won’t be infected."), ("Uminom ka ng gamot nang maibsan naman ang sakit na nararamdaman mo.", "Take medicine so the pain you feel is eased."), ("Namamaga na naman ang lalamunan ko.", "My throat is swollen again."), ("Namamalat ako, bigyan mo ako ng gamot.", "I have a sore throat, give me medicine."), ("Nananakit ang mga kasu-kasuan ko.", "My joints hurt."), ("Inumin mo ito nang hindi ka nangangati palagi.", "Drink this so you won’t be itchy all the time."), ("Nanginginig ang boses niya.", "His voice is trembling."), ("Natuyo na ang singaw ko sa bibig.", "My canker sore in my mouth has dried up."), ("Nilalagnat siya, lagyan mo ng basang bimpo ang noo.", "He has a fever, put a wet face towel on his forehead."), ("Niluto na niya ang paboritong ulam ng kanyang manugang.", "She already cooked her daughter-in-law’s favorite dish."), ("Nireseta ng doktor ang gamot na yan kaya kailangan mong inumin.", "The doctor prescribed that medicine so you need to take it."), ("Niyakap ko si tatay nang mahigpit na mahigpit.", "I hugged Father very tightly."), ("Painumin mo naman ako ng tubig.", "Please give me water to drink."), ("Pinamumog mo na ba ng maligamgam na tubig na may asin si Jojo?", "Have you had Jojo gargle lukewarm salt water yet?"), ("Sinalat ko ang noo niya at totoo ngang may lagnat siya.", "I touched his forehead and he really does have a fever."), ("May bukol na tumutubo sa ilalim ng baba niya.", "There is a lump growing under his chin.")]
_ILL = [("Wala akong alipunga.", "I don’t have athlete’s foot."), ("Ang dami-dami mong an-an sa likod at mukha!", "You have so many an-an on your back and face!"), ("Ano ba ang gamot sa bulutong?", "What is the medicine for chicken pox?"), ("Ang buni ay nagdudulot ng pangangati.", "Ringworm causes itching."), ("Ang butlig ay maliit na bukol sa ibabaw ng balat.", "A blister is a small bump on top of the skin."), ("Ang taas-taas ng lagnat mo!", "Your fever is so high!"), ("Delikado ang pulmonya lalo sa mga bata.", "Pneumonia is dangerous especially for children."), ("Alam mo ba kung ano ang gamot sa singaw?", "Do you know what the medicine for a canker sore is?"), ("May sipon ako kaya hirap akong huminga.", "I have a cold so I have difficulty breathing."), ("Pumunta ka agad sa doktor kapag may tetano ka.", "Go to the doctor right away if you have tetanus."), ("Hindi ako papasok ngayon dahil may trangkaso ako.", "I will not go to work today because I have the flu."), ("Ang lakas ng ubo ko baka mahawa ka.", "My cough is so strong you might get infected.")]
